/* 3D 디지털 트윈 뷰.
 *
 * 무엇이 측정값이고 무엇이 가정인지가 이 화면의 핵심이다.
 *
 *   측정  — 라인 길이(엔코더), 고도각(지상 각도센서), 장력, 풍속,
 *           탑재물 roll/pitch/yaw (9축 AHRS)
 *   보정  — 늘어남 r = L0(1+T/EA), 처짐 δ = wL·cosθ/2T  (둘 다 장력만으로 계산)
 *   가정  — 방위각. 지상국에는 방위 센서가 없다. 연이 어느 쪽에 있는지는
 *           측정되지 않으며, 여기서는 탑재물 yaw를 비행면 방위로 쓴다.
 *           탑재물이 바람에 정렬해 매달린다는 가정이고, 화면에 그렇게 적는다.
 *
 * 2축 각도센서를 달면 방위각이 가정에서 측정으로 바뀐다. 그 전까지
 * 가로 방향 위치는 참고용이다.
 */

import * as THREE from "./vendor/three.module.js";

const C = {
  sky0: 0x0a1016, sky1: 0x16222c,
  ground: 0x16212a, grid: 0x24323d, gridMajor: 0x2f4452,
  kite: 0x52b9e8, kiteEdge: 0x8ad4f5, spar: 0xb9a37a,
  tether: 0x7d93a3, tetherGhost: 0x33454f,
  payload: 0xe8b341, mast: 0x44586a, wind: 0x3d6274,
  ok: 0x4fc99a, warn: 0xe8b341, bad: 0xe8655f,
};

/* ───────────────────────── 궤도 카메라 ─────────────────────────
 * OrbitControls 애드온 대신 직접 둔다. 필요한 건 궤도·줌·팬 세 가지뿐이고,
 * 애드온 하나 때문에 import 경로를 하나 더 관리할 이유가 없다.
 */
class Orbit {
  constructor(camera, dom, target) {
    this.cam = camera;
    this.dom = dom;
    this.target = target.clone();
    this.theta = -0.62;     // 방위
    this.phi = 1.32;        // 천정각. pi/2 가 수평이고, 작을수록 위에서 내려다본다.
    this.radius = 80;
    this.minPhi = 0.08;
    this.maxPhi = Math.PI / 2 - 0.035;   // 지면 아래로 내려가지 않는다
    this.dragging = null;
    this.auto = false;

    dom.addEventListener("pointerdown", e => {
      this.dragging = e.button === 2 || e.shiftKey ? "pan" : "orbit";
      this.px = e.clientX; this.py = e.clientY;
      dom.setPointerCapture(e.pointerId);
      this.auto = false;
    });
    dom.addEventListener("pointermove", e => {
      if (!this.dragging) return;
      const dx = e.clientX - this.px, dy = e.clientY - this.py;
      this.px = e.clientX; this.py = e.clientY;
      if (this.dragging === "orbit") {
        this.theta -= dx * 0.005;
        this.phi = Math.min(this.maxPhi, Math.max(this.minPhi, this.phi - dy * 0.005));
      } else {
        const s = this.radius * 0.0016;
        const right = new THREE.Vector3(Math.cos(this.theta), 0, -Math.sin(this.theta));
        this.target.addScaledVector(right, -dx * s);
        this.target.y = Math.max(0, this.target.y + dy * s);
      }
    });
    const end = e => { this.dragging = null; try { dom.releasePointerCapture(e.pointerId); } catch {} };
    dom.addEventListener("pointerup", end);
    dom.addEventListener("pointercancel", end);
    dom.addEventListener("contextmenu", e => e.preventDefault());
    dom.addEventListener("wheel", e => {
      e.preventDefault();
      this.radius = Math.min(260, Math.max(10, this.radius * (1 + Math.sign(e.deltaY) * 0.1)));
      this.auto = false;
    }, { passive: false });
  }

  set(theta, phi, radius, target) {
    this.theta = theta; this.phi = phi; this.radius = radius;
    if (target) this.target.copy(target);
  }

  update(dt) {
    if (this.auto) this.theta += dt * 0.085;
    const sp = Math.sin(this.phi), cp = Math.cos(this.phi);
    this.cam.position.set(
      this.target.x + this.radius * sp * Math.sin(this.theta),
      this.target.y + this.radius * cp,
      this.target.z + this.radius * sp * Math.cos(this.theta),
    );
    this.cam.lookAt(this.target);
  }
}

/* ───────────────────────── 방패연 ─────────────────────────
 * 사각 캐노피 + 가운데 방구멍 + 대나무 살. 방구멍은 장식이 아니라
 * 이 연의 공력 특성을 정하는 요소라 형상에 반드시 들어가야 한다.
 */
export const KITE_SCALE = 3.2;   // 형상 과장 배율 (HUD에 표기)

/* 실제 0.67 m^2 연은 약 0.8 x 0.84 m 라, 50 m 거리에서 실물 크기로 그리면
 * 점으로 보인다. 자세를 읽으려면 과장이 필요하고, 과장했다는 사실은
 * 화면에 적는다. */
function buildKite(width = 2.6, height = 3.2) {
  const g = new THREE.Group();
  const hw = width / 2, hh = height / 2;
  const vent = height / 3 / 2;          // 방구멍 지름 = 세로의 1/3

  const shape = new THREE.Shape();
  shape.moveTo(-hw, -hh);
  shape.lineTo(hw, -hh);
  shape.lineTo(hw, hh);
  shape.lineTo(-hw, hh);
  shape.closePath();
  const hole = new THREE.Path();
  hole.absarc(0, 0, vent, 0, Math.PI * 2, true);
  shape.holes.push(hole);

  const canopy = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshStandardMaterial({
      color: C.kite, side: THREE.DoubleSide,
      roughness: 0.78, metalness: 0.0,
      emissive: C.kite, emissiveIntensity: 0.1,
    }),
  );
  g.add(canopy);

  const edge = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.ShapeGeometry(shape)),
    new THREE.LineBasicMaterial({ color: C.kiteEdge, transparent: true, opacity: 0.85 }),
  );
  g.add(edge);

  // 대나무 살: 세로 중살, 가로 허릿살, 대각선 둘
  const sparMat = new THREE.MeshStandardMaterial({ color: C.spar, roughness: 0.9 });
  const spar = (len, rot, pos) => {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, len, 6), sparMat);
    m.rotation.z = rot;
    m.position.copy(pos);
    return m;
  };
  g.add(spar(height, 0, new THREE.Vector3(0, 0, 0.02)));
  g.add(spar(width, Math.PI / 2, new THREE.Vector3(0, hh * 0.42, 0.02)));
  const diag = Math.hypot(width, height);
  const a = Math.atan2(height, width);
  g.add(spar(diag, a + Math.PI / 2, new THREE.Vector3(0, 0, 0.02)));
  g.add(spar(diag, -a + Math.PI / 2, new THREE.Vector3(0, 0, 0.02)));

  return g;
}

function buildPayload() {
  const g = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.BoxGeometry(1.5, 0.22, 1.05),
    new THREE.MeshStandardMaterial({
      color: C.payload, roughness: 0.45, metalness: 0.25,
      emissive: C.payload, emissiveIntensity: 0.14,
    }),
  );
  g.add(body);
  g.add(new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.BoxGeometry(1.5, 0.22, 1.05)),
    new THREE.LineBasicMaterial({ color: 0xffd98a, transparent: true, opacity: 0.6 }),
  ));
  // 패널 법선: 입사각이 발전량을 좌우하므로 어느 쪽을 보는지 보여준다
  const n = new THREE.ArrowHelper(
    new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0.09, 0), 1.1, C.payload, 0.3, 0.16);
  n.line.material.transparent = true; n.line.material.opacity = 0.5;
  g.add(n);
  return g;
}

/* ───────────────────────── 장면 ───────────────────────── */

export class TwinScene {
  constructor(host) {
    this.host = host;
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    host.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(C.sky0);
    this.scene.fog = new THREE.Fog(C.sky0, 150, 330);

    this.camera = new THREE.PerspectiveCamera(42, 1, 0.3, 900);
    this.orbit = new Orbit(this.camera, this.renderer.domElement, new THREE.Vector3(14, 14, 0));

    this._lights();
    this._ground();
    this._station();
    this._flight();

    // When two panes are linked, one drives and the other follows. A follower
    // that keeps re-framing itself fights the pane driving it, once per frame.
    this.autoFrame = true;

    this.clock = new THREE.Clock();
    this._resize();
    this._ro = new ResizeObserver(() => this._resize());
    this._ro.observe(host);
  }

  _lights() {
    this.scene.add(new THREE.HemisphereLight(0x486a84, 0x0e1419, 1.5));
    const sun = new THREE.DirectionalLight(0xfff0d8, 1.9);
    sun.position.set(42, 58, 34);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1024, 1024);
    const d = 60;
    Object.assign(sun.shadow.camera, { left: -d, right: d, top: d, bottom: -d, near: 1, far: 190 });
    this.scene.add(sun);
    this.sun = sun;
  }

  _ground() {
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(170, 64).rotateX(-Math.PI / 2),
      new THREE.MeshStandardMaterial({ color: C.ground, roughness: 1 }),
    );
    ground.receiveShadow = true;
    ground.position.y = -0.01;
    this.scene.add(ground);

    const grid = new THREE.GridHelper(200, 40, C.gridMajor, C.grid);
    grid.material.transparent = true;
    grid.material.opacity = 0.42;
    this.scene.add(grid);

    // 10 m 간격 거리 링. 고도·거리를 눈대중할 기준이 없으면 3D는 읽히지 않는다.
    for (let r = 10; r <= 90; r += 20) {
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(r - 0.07, r + 0.07, 96).rotateX(-Math.PI / 2),
        new THREE.MeshBasicMaterial({ color: C.gridMajor, transparent: true, opacity: 0.5,
                                      side: THREE.DoubleSide }),
      );
      ring.position.y = 0.02;
      this.scene.add(ring);
    }
  }

  _station() {
    const g = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color: C.mast, roughness: 0.6, metalness: 0.3 });

    const base = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.35, 1.6), mat);
    base.position.y = 0.18; base.castShadow = true;
    g.add(base);
    const drum = new THREE.Mesh(
      new THREE.CylinderGeometry(0.42, 0.42, 1.0, 20).rotateZ(Math.PI / 2), mat);
    drum.position.y = 0.72; drum.castShadow = true;
    g.add(drum);

    // 풍속계 마스트 — 설치 높이는 기록해야 하는 값이라 눈에 보이게 둔다
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 10, 8), mat);
    mast.position.set(-5, 5, 3);
    g.add(mast);
    const cup = new THREE.Mesh(
      new THREE.SphereGeometry(0.22, 12, 10),
      new THREE.MeshStandardMaterial({ color: C.ok, emissive: C.ok, emissiveIntensity: 0.3 }));
    cup.position.set(-5, 10.1, 3);
    g.add(cup);
    this.anemo = cup;

    this.scene.add(g);
  }

  _flight() {
    this.kite = buildKite();
    this.kite.castShadow = true;
    this.kite.traverse(o => { if (o.isMesh) o.castShadow = true; });
    this.scene.add(this.kite);

    this.payload = buildPayload();
    this.payload.traverse(o => { if (o.isMesh) o.castShadow = true; });
    this.scene.add(this.payload);

    // 계류줄: 처짐을 반영한 곡선. 보정 전 직선은 흐리게 같이 그린다.
    this.tetherGeo = new THREE.BufferGeometry();
    this.tetherGeo.setAttribute("position",
      new THREE.BufferAttribute(new Float32Array(3 * 33), 3));
    this.tether = new THREE.Line(this.tetherGeo,
      new THREE.LineBasicMaterial({ color: C.tether }));
    this.scene.add(this.tether);

    this.ghostGeo = new THREE.BufferGeometry();
    this.ghostGeo.setAttribute("position",
      new THREE.BufferAttribute(new Float32Array(3 * 2), 3));
    this.ghost = new THREE.Line(this.ghostGeo,
      new THREE.LineDashedMaterial({ color: C.tetherGhost, dashSize: 1.4, gapSize: 1.0 }));
    this.scene.add(this.ghost);

    this.drop = new THREE.Line(
      new THREE.BufferGeometry().setAttribute("position",
        new THREE.BufferAttribute(new Float32Array(6), 3)),
      new THREE.LineBasicMaterial({ color: C.payload, transparent: true, opacity: 0.65 }));
    this.scene.add(this.drop);

    // 방위 불확실성: 지면에 눕힌 부채꼴. 수직 반투명 판으로 그렸더니 회색 벽이
    // 되어 연을 가렸다 — 가정을 알리자고 측정값을 못 보게 만들 수는 없다.
    // 바닥에 누우면 '연은 이 방향 어딘가'를 말하면서 시야를 비운다.
    const WEDGE = THREE.MathUtils.degToRad(25);
    this.wedge = new THREE.Mesh(
      new THREE.CircleGeometry(1, 40, Math.PI / 2 - WEDGE, 2 * WEDGE)
        .rotateX(-Math.PI / 2),
      new THREE.MeshBasicMaterial({ color: 0x52b9e8, transparent: true,
                                    opacity: 0.09, side: THREE.DoubleSide,
                                    depthWrite: false }),
    );
    this.wedge.position.y = 0.05;
    this.scene.add(this.wedge);

    // 연 바로 아래 지면까지의 수선 — 고도를 눈으로 읽는 기준
    this.plumb = new THREE.Line(
      new THREE.BufferGeometry().setAttribute("position",
        new THREE.BufferAttribute(new Float32Array(6), 3)),
      new THREE.LineDashedMaterial({ color: 0x3f5666, dashSize: 1.1, gapSize: 0.9 }));
    this.scene.add(this.plumb);

    this.windArrow = new THREE.ArrowHelper(
      new THREE.Vector3(1, 0, 0), new THREE.Vector3(-22, 12, 0), 10, C.wind, 2.4, 1.3);
    this.scene.add(this.windArrow);
  }

  _resize() {
    const w = this.host.clientWidth, h = this.host.clientHeight;
    if (!w || !h) return;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  /* 프리셋은 비행면을 기준으로 잡는다.
   *
   * 카메라 방위를 월드 고정값으로 두면 '측면'이 비행면과 나란히 서서 연을
   * 정면에서 보게 된다 — 줄이 수직선 하나로 뭉개지고 고도각이 안 읽힌다.
   * 비행면 방위(az)를 기준으로 삼아야 '측면'이 실제로 옆모습이 된다.
   *
   * az 는 누를 때 한 번만 읽는다. 매 프레임 따라가면 yaw 잡음만큼 화면이 돈다.
   */
  preset(name) {
    const t = this.frameTarget ?? new THREE.Vector3(0, 21, 0);
    const R = this.framedFor ? this.framedFor * 1.5 : 80;
    const az = this.az || 0;
    if (name === "side")  this.orbit.set(az, Math.PI / 2 - 0.06, R, t);
    if (name === "top")   this.orbit.set(az - 0.62, 0.16, R * 1.15, t);
    if (name === "chase") this.orbit.set(az - Math.PI / 2, 1.2, R * 0.75, t);
    if (name === "wide")  this.orbit.set(az - 0.62, 1.32, R, t);
    this.orbit.auto = false;
  }

  toggleSpin() { this.orbit.auto = !this.orbit.auto; return this.orbit.auto; }

  /** 카메라 상태를 꺼내고 넣는다 — 분할 뷰를 묶는 데 쓴다. */
  cameraState() {
    const o = this.orbit;
    return { theta: o.theta, phi: o.phi, radius: o.radius,
             tx: o.target.x, ty: o.target.y, tz: o.target.z, auto: o.auto };
  }

  applyCameraState(c) {
    if (!c) return;
    const o = this.orbit;
    o.theta = c.theta;
    o.phi = c.phi;
    o.radius = c.radius;
    o.target.set(c.tx, c.ty, c.tz);
    o.auto = c.auto;
  }

  /** 이 장면을 사용자가 직접 건드렸는지 알려준다(묶기 방향 결정용). */
  onInteract(fn) {
    this.renderer.domElement.addEventListener("pointerdown", fn);
    this.renderer.domElement.addEventListener("wheel", fn, { passive: true });
  }

  /** 한 프레임의 텔레메트리를 장면에 반영한다. */
  apply(f) {
    if (!f) return;
    const d = f.derived, raw = f.raw;
    const flying = d.chord_deg > 2 && d.z > 0;

    // 방위각: 측정값이 아니라 탑재물 yaw에서 가져온 가정값
    const az = THREE.MathUtils.degToRad(raw.yaw || 0);
    this.az = az;
    const ca = Math.cos(az), sa = Math.sin(az);
    const toWorld = (x, y) => new THREE.Vector3(x * ca, y, -x * sa);

    const elev = THREE.MathUtils.degToRad(d.chord_deg);
    const horiz = d.span * Math.cos(elev);
    const kitePos = toWorld(horiz, Math.max(d.z, 0));

    this.kite.visible = this.payload.visible = flying;
    this.tether.visible = this.ghost.visible = this.drop.visible = flying;
    this.wedge.visible = this.plumb.visible = flying;
    if (!flying) return;

    // 연: 양력이 겉보기바람에 수직이고 줄 바깥쪽이라는 브라이들 가정 →
    // 캐노피 법선이 대략 줄 방향을 향한다. 측정된 자세가 아니라 모델이다.
    this.kite.position.copy(kitePos);
    this.kite.lookAt(0, 0, 0);
    this.kite.rotateY(Math.PI);
    this.kite.rotateZ(THREE.MathUtils.degToRad(raw.roll || 0) * 0.5);

    // 계류줄: 현을 따라가되 처짐만큼 아래로 휘는 2차 곡선
    const sag = Math.tan(THREE.MathUtils.degToRad(d.sag_deg)) * d.span / 2;
    const pos = this.tetherGeo.attributes.position;
    const n = pos.count;
    for (let i = 0; i < n; i++) {
      const u = i / (n - 1);
      const p = kitePos.clone().multiplyScalar(u);
      p.y -= 4 * sag * u * (1 - u);        // 양 끝 0, 가운데 최대
      pos.setXYZ(i, p.x, Math.max(p.y, 0), p.z);
    }
    pos.needsUpdate = true;
    this.tetherGeo.computeBoundingSphere();

    // 보정 전 위치: 엔코더 길이 + 측정 각도 그대로
    const ghostPos = toWorld(d.x_raw, Math.max(d.z_raw, 0));
    const gp = this.ghostGeo.attributes.position;
    gp.setXYZ(0, 0, 0, 0);
    gp.setXYZ(1, ghostPos.x, ghostPos.y, ghostPos.z);
    gp.needsUpdate = true;
    this.ghost.computeLineDistances();

    // 탑재물: 흔들림 각도만큼 기운 채 목줄에 매달린다.
    // 목줄 0.5 m는 라인 50 m 옆에서 1%라 실측 비율로 그리면 연에 붙어버리고,
    // 흔들림 — 이 화면에서 제일 보고 싶은 것 — 이 안 보인다. 연 형상과 같은
    // 배율로 늘려 그리고, 그 사실을 화면에 적는다. 각도는 손대지 않는다.
    const pRaw = toWorld(d.payload_x, d.payload_z);
    const pPos = pRaw.clone().sub(kitePos).multiplyScalar(KITE_SCALE).add(kitePos);
    pPos.y = Math.max(pPos.y, 0);
    this.payload.position.copy(pPos);
    this.payload.rotation.set(
      THREE.MathUtils.degToRad(raw.roll || 0),
      az,
      THREE.MathUtils.degToRad(raw.pitch || 0),
    );
    const dp = this.drop.geometry.attributes.position;
    dp.setXYZ(0, kitePos.x, kitePos.y, kitePos.z);
    dp.setXYZ(1, pPos.x, pPos.y, pPos.z);
    dp.needsUpdate = true;

    this.wedge.scale.setScalar(Math.max(horiz, 1));
    this.wedge.rotation.set(-Math.PI / 2, 0, az - Math.PI / 2);

    const pl = this.plumb.geometry.attributes.position;
    pl.setXYZ(0, kitePos.x, 0, kitePos.z);
    pl.setXYZ(1, kitePos.x, kitePos.y, kitePos.z);
    pl.needsUpdate = true;
    this.plumb.computeLineDistances();

    const ws = Math.max(raw.wind, 0.5);
    this.windArrow.position.set(-26 * ca, 6, 26 * sa);
    this.windArrow.setDirection(new THREE.Vector3(ca, 0, -sa));
    this.windArrow.setLength(3 + ws * 1.5, 2.4, 1.3);

    const frac = raw.tension / (f.limits?.design_load || 50);
    const col = frac > 1 ? C.bad : frac > 0.7 ? C.warn : C.tether;
    this.tether.material.color.setHex(col);

    this._frame(d.span);
  }

  /* 카메라는 고정한다.
   *
   * 처음에는 시선을 연에 붙여 따라가게 했는데, 그러면 연이 화면 가운데
   * 못 박힌 채 세상이 움직인다 — 보고 싶은 건 연의 움직임인데 정확히 그것만
   * 안 보인다. 그래서 시선을 윈치 위 한 점에 묶고, 연이 화면 안에서
   * 돌아다니게 둔다.
   *
   * 다시 잡는 건 라인 길이가 크게 바뀌었을 때뿐이다. 매 프레임 다시 잡으면
   * 장력에 따라 경사거리가 cm 단위로 흔들려 화면이 미세하게 계속 떤다.
   */
  _frame(span) {
    if (this.framedFor && Math.abs(span - this.framedFor) / this.framedFor < 0.25) return;
    this.framedFor = span;
    // 방위각과 무관한 점이라야 yaw가 흔들려도 화면이 따라 흔들리지 않는다.
    // 높이는 비행 범위(고도각 20~60°)의 한가운데에 둔다 — 윈치에 맞추면
    // 화면 절반이 땅이고 연은 위쪽 구석에 걸린다.
    this.frameTarget = new THREE.Vector3(span * 0.22, span * 0.46, 0);
    // frameTarget is still recorded when auto-framing is off, because the
    // view presets are written against it.
    if (!this.autoFrame) return;
    this.orbit.target.copy(this.frameTarget);
    this.orbit.radius = span * 1.5;
    if (!this.aimed) {
      this.aimed = true;
      this.orbit.theta = (this.az || 0) - 0.62;
    }
  }

  render() {
    this.orbit.update(Math.min(this.clock.getDelta(), 0.1));
    this.renderer.render(this.scene, this.camera);
  }
}

station/style.css.text:
/* 방패연 지상국 모니터 — 계기판 스타일시트
 *
 * 색은 토큰으로만 쓴다. 상태색(정상/주의/경고)은 세 군데에서 쓰이므로
 * 값이 한 곳에 있어야 한다.
 */

:root {
  --bg:        #0b1116;
  --surface:   #121b22;
  --surface-2: #17222b;
  --surface-3: #1d2a34;
  --line:      #22323d;
  --line-soft: #1a2832;

  --ink:       #e3ecf2;
  --ink-2:     #9fb2bf;
  --ink-3:     #6b7f8d;

  --accent:    #52b9e8;
  --accent-dim:#2d5f7a;
  --ok:        #4fc99a;
  --warn:      #e8b341;
  --bad:       #e8655f;
  --payload:   #e8b341;

  --mono: "Consolas", "D2Coding", ui-monospace, monospace;
  --sans: "Pretendard", "Malgun Gothic", "맑은 고딕", system-ui, sans-serif;

  --r: 10px;
  --gap: 13px;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}

/* ─────────────────────────── 상단 바 ─────────────────────────── */

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 54px;
  padding: 0 18px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.brand { display: flex; align-items: baseline; gap: 10px; }
.brand h1 { font-size: 15px; font-weight: 700; margin: 0; letter-spacing: -0.1px; }
.brand .sub { font-size: 11.5px; color: var(--ink-3); }

.badge {
  font-size: 11px; font-weight: 700; letter-spacing: .3px;
  padding: 4px 10px; border-radius: 20px;
  background: var(--surface-3); color: var(--accent);
  border: 1px solid var(--accent-dim);
}
.badge.live { background: #14301f; color: var(--ok); border-color: #2a5c43; }

.grow { flex: 1 1 auto; }

.statgroup { display: flex; align-items: center; gap: 22px; }
.stat { text-align: right; line-height: 1.3; min-width: 62px; }
.stat .k { font-size: 9.5px; color: var(--ink-3); letter-spacing: .7px; text-transform: uppercase; }
.stat .v { font-family: var(--mono); font-size: 13.5px; font-variant-numeric: tabular-nums; }

.link-state { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--ink-2); }
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--bad); flex: none; }
.dot.on    { background: var(--ok); box-shadow: 0 0 8px rgba(79,201,154,.6); }
.dot.stale { background: var(--warn); box-shadow: 0 0 8px rgba(232,179,65,.5); }

/* ─────────────────────────── 레이아웃 ─────────────────────────── */

.shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  /* 행에도 minmax(0,1fr)을 줘야 한다. 기본 auto 행은 내용 높이를 그대로
   * 따라가서, height 를 지정해도 3D 카드가 넘쳐 시계열이 화면 밖으로 밀린다. */
  grid-template-rows: minmax(0, 1fr);
  gap: var(--gap);
  padding: var(--gap);
  height: calc(100% - 54px);
}

.left  { display: grid; grid-template-rows: minmax(0, 1fr) 206px; gap: var(--gap);
         min-width: 0; min-height: 0; }
.right { display: flex; flex-direction: column; gap: var(--gap); overflow-y: auto; padding-right: 2px; }

/* 우측 카드는 내용 높이를 지킨다. flex 기본값(shrink:1)을 두면 스크롤 대신
 * 카드끼리 눌려 겹친다. */
.right > .card { flex: 0 0 auto; }

.right::-webkit-scrollbar { width: 8px; }
.right::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }
.right::-webkit-scrollbar-track { background: transparent; }

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.card > header {
  display: flex; align-items: center; gap: 9px;
  padding: 11px 14px 9px;
  flex: none;
}
.card > header h2 {
  font-size: 10.5px; font-weight: 700; margin: 0;
  color: var(--ink-3); letter-spacing: 1.2px; text-transform: uppercase;
}
.card > header .note { font-size: 11px; color: var(--ink-3); margin-left: auto; }
.card > .body { padding: 0 14px 13px; min-height: 0; flex: 1 1 auto; }
.card.flush > .body { padding: 0; }

/* ─────────────────────────── 3D 뷰 ─────────────────────────── */

.viewport { position: relative; border-radius: var(--r); overflow: hidden; background: #080d12; }
.viewport canvas { display: block; width: 100%; height: 100%; }

.hud {
  position: absolute; pointer-events: none;
  font-family: var(--mono); font-variant-numeric: tabular-nums;
}
.hud.tl { top: 12px; left: 14px; }
.hud.tr { top: 12px; right: 14px; text-align: right; }
.hud.bl { bottom: 12px; left: 14px; }

.hud .row { font-size: 12px; color: var(--ink-2); margin-bottom: 3px; }
.hud .row b { color: var(--ink); font-weight: 600; }
.hud .big { font-size: 22px; color: var(--ink); letter-spacing: -0.4px; }
.hud .cap { font-family: var(--sans); font-size: 10px; color: var(--ink-3);
            letter-spacing: .8px; text-transform: uppercase; }

.viewctl {
  position: absolute; top: 10px; right: 12px;
  display: flex; gap: 5px; pointer-events: auto;
}
.viewctl button {
  font-family: var(--sans); font-size: 11px; color: var(--ink-2);
  background: rgba(23,34,43,.88); border: 1px solid var(--line);
  border-radius: 6px; padding: 5px 10px; cursor: pointer;
  backdrop-filter: blur(6px);
}
.viewctl button:hover { color: var(--ink); border-color: var(--accent-dim); }
.viewctl button.on { color: var(--accent); border-color: var(--accent-dim); background: #15293550; }

.inferred {
  position: absolute; left: 14px; bottom: 12px;
  font-size: 10.5px; color: var(--ink-3);
  background: rgba(11,17,22,.7); padding: 4px 9px; border-radius: 5px;
  border-left: 2px solid var(--warn);
}

/* ─────────────────────────── 계기 ─────────────────────────── */

.tiles { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.tile { background: var(--surface-2); border-radius: 7px; padding: 9px 11px; }
.tile .k { font-size: 9.5px; color: var(--ink-3); letter-spacing: .6px; text-transform: uppercase; }
.tile .v { font-family: var(--mono); font-size: 20px; margin-top: 2px;
           font-variant-numeric: tabular-nums; letter-spacing: -0.5px; }
.tile .v u { font-size: 11px; color: var(--ink-3); text-decoration: none; margin-left: 2px; }
.tile.warn  .v { color: var(--warn); }
.tile.alert .v { color: var(--bad); }

table.kv { width: 100%; border-collapse: collapse; font-size: 12.5px; }
table.kv td { padding: 6px 0; border-bottom: 1px solid var(--line-soft); vertical-align: top; }
table.kv tr:last-child td { border-bottom: none; }
table.kv td:last-child { text-align: right; font-family: var(--mono);
                         font-variant-numeric: tabular-nums; white-space: nowrap; }
table.kv .sub { display: block; color: var(--ink-3); font-size: 10.5px; line-height: 1.4; }
table.kv .muted { color: var(--ink-3); }

.meter { margin-top: 10px; }
.meter .track { height: 7px; background: var(--surface-3); border-radius: 4px;
                overflow: hidden; position: relative; }
.meter .fill { height: 100%; background: var(--ok); border-radius: 4px;
               transition: width .12s linear, background .2s; }
.meter .fill.warn { background: var(--warn); }
.meter .fill.bad  { background: var(--bad); }
.meter .scale { display: flex; justify-content: space-between;
                font-size: 10px; color: var(--ink-3); margin-top: 5px; }

.gate { display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; }
.gate .pip { width: 6px; height: 6px; border-radius: 50%; background: var(--ink-3); }
.gate.open .pip { background: var(--ok); }

.empty { color: var(--ink-3); font-size: 12px; text-align: center; padding: 18px 0; }

canvas.strip { display: block; width: 100%; }

footer.tips {
  font-size: 10.5px; color: var(--ink-3); padding: 2px 4px 0; line-height: 1.6;
}
footer.tips code { font-family: var(--mono); background: var(--surface-2);
                   padding: 1px 5px; border-radius: 3px; color: var(--ink-2); }

@media (max-width: 1240px) {
  .shell { grid-template-columns: 1fr; grid-template-rows: auto; height: auto; overflow-y: auto; }
  body { overflow: auto; }
  .left { grid-template-rows: 460px 212px; }
  .right { overflow: visible; }
}

/* 모의 데이터일 때는 배지가 실측처럼 보이면 안 된다 */
.badge.sim { background: #33280f; color: var(--warn); border-color: #5c4a1e; }
.inferred b { color: var(--warn); }

/* ───────────── 소스 전환 / 분할 / 설정 ───────────── */

.seg { display: flex; gap: 2px; background: var(--surface-2);
       border: 1px solid var(--line); border-radius: 7px; padding: 2px; }
.seg button {
  font-family: var(--sans); font-size: 11.5px; color: var(--ink-3);
  background: none; border: none; border-radius: 5px;
  padding: 5px 11px; cursor: pointer; white-space: nowrap;
}
.seg button:hover { color: var(--ink-2); }
.seg button.on { background: var(--surface-3); color: var(--ink); }
.seg button:disabled { opacity: .45; cursor: default; }

.panes { display: grid; grid-template-columns: 1fr; gap: 0; height: 100%;
         border-radius: var(--r); overflow: hidden; }
.panes.split { grid-template-columns: 1fr 1fr; gap: 2px; }
.panes .viewport { height: 100%; border-radius: 0; }

.paneTag {
  position: absolute; left: 50%; transform: translateX(-50%); top: 10px;
  font-size: 10.5px; letter-spacing: 1.4px; color: var(--ink-3);
  background: rgba(11,17,22,.72); padding: 3px 11px; border-radius: 12px;
  pointer-events: none;
}
.paneTag.pred { color: var(--warn); }

.divbar { position: absolute; left: 14px; bottom: 12px; right: 14px;
          font-family: var(--mono); font-size: 11.5px; color: var(--ink-2); }

.field { display: grid; grid-template-columns: 1fr auto; align-items: center;
         gap: 6px; margin-bottom: 7px; }
.field label { font-size: 11.5px; color: var(--ink-2); }
.field label .u { color: var(--ink-3); font-size: 10px; }
.field input[type=range] { grid-column: 1 / -1; width: 100%; height: 3px;
  -webkit-appearance: none; background: var(--surface-3); border-radius: 2px; }
.field input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none; width: 13px; height: 13px; border-radius: 50%;
  background: var(--accent); cursor: pointer; }
.field output { font-family: var(--mono); font-size: 12px; color: var(--ink);
                font-variant-numeric: tabular-nums; }
.field.check { grid-template-columns: auto 1fr; }
.field.check input { accent-color: var(--accent); }

button.apply {
  width: 100%; margin-top: 9px; padding: 8px; cursor: pointer;
  font-family: var(--sans); font-size: 12px; font-weight: 700;
  color: #0b1116; background: var(--accent); border: none; border-radius: 6px;
}
button.apply:disabled { background: var(--surface-3); color: var(--ink-3); cursor: default; }
button.mini {
  font-family: var(--sans); font-size: 10.5px; color: var(--ink-3);
  background: none; border: 1px solid var(--line); border-radius: 5px;
  padding: 2px 7px; cursor: pointer;
}
button.mini:hover { color: var(--ink-2); }
.simnote { font-size: 10.5px; color: var(--ink-3); margin-top: 8px; line-height: 1.55; }
.delta.pos { color: var(--warn); } .delta.neg { color: var(--accent); }

/* [hidden] 은 UA 스타일시트의 display:none 인데, .card 의 display:flex 가
 * 명시도에서 이긴다. 숨긴 카드가 그대로 보이는 원인이라 못을 박아둔다. */
[hidden] { display: none !important; }


/* ───────────── 포트 선택 ───────────── */

.modal { position: fixed; inset: 0; z-index: 40; display: grid;
         place-items: center; background: rgba(6,10,13,.72);
         backdrop-filter: blur(3px); }
.modal .sheet {
  width: min(460px, calc(100vw - 32px));
  background: var(--surface); border: 1px solid var(--line);
  border-radius: 12px; padding: 16px 18px 18px;
  box-shadow: 0 18px 50px rgba(0,0,0,.5);
}
.modal header { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.modal h3 { font-size: 14px; margin: 0; flex: 1; }

.portlist { display: flex; flex-direction: column; gap: 6px; }
.portrow {
  display: flex; align-items: center; gap: 10px;
  background: var(--surface-2); border-radius: 7px; padding: 9px 11px;
}
.portrow .nm { font-family: var(--mono); font-size: 12.5px; }
.portrow .ds { font-size: 11px; color: var(--ink-3); flex: 1;
               overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.portrow .pip { width: 7px; height: 7px; border-radius: 50%;
                background: var(--ok); flex: none; }
.portrow.absent .pip { background: var(--ink-3); }
.portrow.absent .nm { color: var(--ink-3); }
.portrow.on { outline: 1px solid var(--accent-dim); }
.portrow button {
  font-family: var(--sans); font-size: 11px; color: var(--ink-2);
  background: var(--surface-3); border: 1px solid var(--line);
  border-radius: 5px; padding: 4px 10px; cursor: pointer;
}
.portrow button:hover { color: var(--ink); border-color: var(--accent-dim); }

.manual { margin-top: 14px; border-top: 1px solid var(--line); padding-top: 12px; }
.manual label { font-size: 11px; color: var(--ink-3); }
.manual .row { display: flex; gap: 7px; margin-top: 6px; }
.manual input {
  flex: 1; font-family: var(--mono); font-size: 12.5px; color: var(--ink);
  background: var(--surface-2); border: 1px solid var(--line);
  border-radius: 6px; padding: 7px 9px;
}
.manual input:focus { outline: none; border-color: var(--accent-dim); }
button.apply.narrow { width: auto; margin-top: 0; padding: 7px 14px; }

.banner {
  position: absolute; inset: 0; display: grid; place-items: center;
  background: rgba(11,17,22,.82); z-index: 5; text-align: center;
}
.banner .inner { max-width: 340px; }
.banner h4 { margin: 0 0 6px; font-size: 14px; color: var(--bad); }
.banner p { margin: 0 0 12px; font-size: 12px; color: var(--ink-2); line-height: 1.6; }


.rec { display: inline-flex; align-items: center; gap: 6px; font-size: 11px;
       color: var(--ink-3); font-family: var(--mono); }
.rec .pip { width: 7px; height: 7px; border-radius: 50%; background: var(--bad);
            animation: recblink 2s ease-in-out infinite; }
@keyframes recblink { 0%,100% { opacity: 1 } 50% { opacity: .35 } }
@media (prefers-reduced-motion: reduce) { .rec .pip { animation: none } }

firmware/common/ebimu_parse.h.text:
// EBIMU ASCII frame parsing, kept free of Arduino headers so it can be
// compiled and tested on a host machine.
//
// A frame is '*' then comma-separated floats then CRLF. The field count
// depends on how the module was configured and differs between board
// revisions, so the parser takes whatever floats it finds and reports how
// many -- the caller decides whether that count is the mode it expected.

#pragma once

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

#define EBIMU_MAX_FIELDS 8
#define EBIMU_MIN_FIELDS 3

typedef struct {
  float values[EBIMU_MAX_FIELDS];
  uint8_t count;
} EbimuFrame;

// `line` is the frame body, with the leading '*' and trailing CRLF removed.
// Rejects the frame outright if it finds anything that is not a number where
// one belongs: a line carrying evidence of corruption should be dropped rather
// than half-trusted, and at 50 Hz losing a frame costs nothing. Also rejects
// frames with fewer than three floats, which carry no usable attitude.
static inline bool ebimu_parse(const char *line, EbimuFrame *out) {
  out->count = 0;
  if (line == NULL) {
    return false;
  }

  const char *p = line;
  while (*p != '\0' && out->count < EBIMU_MAX_FIELDS) {
    char *end = NULL;
    float v = strtof(p, &end);
    if (end == p) {
      return false;  // garbage where a number belongs -- drop the frame
    }
    out->values[out->count++] = v;

    p = end;
    while (*p == ' ' || *p == '\t') {
      p++;
    }
    if (*p == ',') {
      p++;
    } else {
      break;
    }
  }

  return out->count >= EBIMU_MIN_FIELDS;
}

firmware/common/iv_sweep.h.text:
// Reducing a capacitor-charge IV sweep to the numbers worth transmitting.
//
// Kept free of Arduino and I2C so it can be compiled and tested on a host.
// The sweep itself is: short the capacitor, release it, and sample voltage and
// current while the panel charges it from 0 up to Voc. Samples therefore run
// from short-circuit towards open-circuit.
//
// Isc and Voc are extrapolated rather than read off the ends: the first sample
// is never exactly at V=0 and the last never exactly at I=0.

#pragma once

#include <stdbool.h>
#include <stdint.h>

#define IV_EDGE_POINTS 5        // samples averaged into each end fit
#define IV_MIN_POINTS 8

typedef struct {
  float pmax;     // W
  float vmp;      // V at the maximum power point
  float imp;      // A at the maximum power point
  float voc;      // V, extrapolated to zero current
  float isc;      // A, extrapolated to zero voltage
  float fill;     // pmax / (voc * isc)
  uint16_t count; // samples used
  bool valid;
} IvResult;

// Least-squares slope and intercept of y against x over n points.
static inline bool iv_fit(const float *x, const float *y, int n,
                          float *slope, float *intercept) {
  if (n < 2) {
    return false;
  }
  float sx = 0.0f, sy = 0.0f, sxx = 0.0f, sxy = 0.0f;
  for (int k = 0; k < n; k++) {
    sx += x[k];
    sy += y[k];
    sxx += x[k] * x[k];
    sxy += x[k] * y[k];
  }
  float denom = n * sxx - sx * sx;
  if (denom > -1e-12f && denom < 1e-12f) {
    return false;   // all samples at one x; no slope to find
  }
  *slope = (n * sxy - sx * sy) / denom;
  *intercept = (sy - *slope * sx) / n;
  return true;
}

// `volts` and `amps` run from short-circuit towards open-circuit.
static inline IvResult iv_analyse(const float *volts, const float *amps,
                                  int n) {
  IvResult out = {0};
  out.count = (uint16_t)(n < 0 ? 0 : n);
  if (volts == 0 || amps == 0 || n < IV_MIN_POINTS) {
    return out;
  }

  int best = 0;
  float best_power = -1.0f;
  for (int k = 0; k < n; k++) {
    float p = volts[k] * amps[k];
    if (p > best_power) {
      best_power = p;
      best = k;
    }
  }
  if (best_power <= 0.0f) {
    return out;    // dark panel, or the sweep never ran
  }

  int edge = n < IV_EDGE_POINTS * 2 ? n / 2 : IV_EDGE_POINTS;

  // Isc: current extrapolated back to V = 0, from the low-voltage end.
  float slope, intercept;
  out.isc = iv_fit(volts, amps, edge, &slope, &intercept) ? intercept : amps[0];

  // Voc: voltage extrapolated to I = 0, fitting V against I at the far end.
  const float *v_tail = volts + (n - edge);
  const float *i_tail = amps + (n - edge);
  out.voc = iv_fit(i_tail, v_tail, edge, &slope, &intercept) ? intercept
                                                             : volts[n - 1];

  out.pmax = best_power;
  out.vmp = volts[best];
  out.imp = amps[best];

  // A fit through noise can land the intercept below the data it came from.
  if (out.isc < out.imp) {
    out.isc = out.imp;
  }
  if (out.voc < out.vmp) {
    out.voc = out.vmp;
  }

  out.fill = (out.voc > 0.0f && out.isc > 0.0f)
                 ? out.pmax / (out.voc * out.isc)
                 : 0.0f;
  out.valid = out.fill > 0.1f && out.fill <= 1.0f;
  return out;
}

